package com.distributedexam.client.ui;
import com.distributedexam.client.RMIClientConnector;import com.distributedexam.common.*;import javax.swing.*;import java.awt.*;
public class RoomDashboard extends JFrame {private final RMIClientConnector c;private final User user;private final JTextArea body=new JTextArea(24,85);public RoomDashboard(RMIClientConnector c,User u){super("Room Dashboard - "+u.getUsername());this.c=c;user=u;body.setEditable(false);add(new JScrollPane(body));JPanel p=new JPanel();JButton refresh=new JButton("Refresh");refresh.addActionListener(e->load());JButton incident=new JButton("Report incident");incident.addActionListener(e->report());p.add(refresh);p.add(incident);add(p,BorderLayout.SOUTH);pack();setDefaultCloseOperation(EXIT_ON_CLOSE);setLocationRelativeTo(null);load();}private void load(){if(user.getRoomId()==null){body.setText("No room is assigned to this account.");return;}try{DashboardSnapshot d=c.getDashboardService().getRoomSnapshot(user.getRoomId());Room r=d.rooms.isEmpty()?null:d.rooms.get(0);String text="Room: "+(r==null?user.getRoomId():r.getRoomName()+" ("+r.getStatus()+")")+"\nCurrent exam: "+(r==null?"none":r.getCurrentExamId())+"\nAttendance: "+d.attendancePercentByRoom+"\nSubmissions: "+d.submissionProgressByRoom+"\nOpen incidents: "+d.openIncidents+"\n\nEvents:\n";for(ExamEvent e:d.recentEvents)text+=e.getEventTimestamp()+" | "+e.getEventType()+" | "+e.getDescription()+"\n";body.setText(text);}catch(Exception e){body.setText("Unable to load server data: "+e.getMessage());}}private void report(){if(user.getRoomId()==null)return;String description=JOptionPane.showInputDialog(this,"Describe the incident:");if(description==null||description.isBlank())return;try{Incident i=new Incident();i.setRoomId(user.getRoomId());i.setType("GENERAL");i.setSeverity("MEDIUM");i.setDescription(description);c.getMonitoringService().reportIncident(i);load();}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Incident failed",JOptionPane.ERROR_MESSAGE);}}}
